xql_query:
// ============================================================
// Rule: WIN_AD Multiple Users Disabled
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_AD Multiple Users Disabled.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1098 - Account Manipulation

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: padronizar comparações e evitar perda de eventos por variações de caixa
config case_sensitive = false

// Fonte de dados: telemetria do agente (inclui Windows Security Event Log)
| dataset = xdr_data

// Filtro: restringe a eventos do Windows Event Log
// Event ID 4725 = "A user account was disabled" (desativação de conta no AD/Windows)
| filter event_type = ENUM.EVENT_LOG
| filter action_evtlog_event_id = 4725

// Extração/normalização de campos do evento 4725 (Security)
// - Subject*: executor (quem desativou)
// - Target*: alvo (conta desativada)
| alter
    SubjectUserName   = action_evtlog_data_fields -> SubjectUserName,    // Usuário executor da desativação
    SubjectDomainName = action_evtlog_data_fields -> SubjectDomainName,  // Domínio do executor
    TargetUserName    = action_evtlog_data_fields -> TargetUserName,     // Conta desativada
    TargetDomainName  = action_evtlog_data_fields -> TargetDomainName,   // Domínio da conta desativada
    TargetSid         = action_evtlog_data_fields -> TargetSid           // SID da conta desativada

// Agrupamento temporal: consolida eventos em janelas de 1 hora para identificar desativação em massa
| bin _time span = 1h

// Agregação: contabiliza quantas contas distintas foram desativadas na janela
// - users_disabled: número de usuários distintos desativados
// - disabled_users/disabled_sids: evidências para investigação
| comp
    count_distinct(TargetUserName) as users_disabled,
    values(TargetUserName) as disabled_users,
    values(TargetSid) as disabled_sids
  by _time, agent_hostname, SubjectDomainName, SubjectUserName

// Threshold: dispara quando houver desativação em massa (ajuste conforme baseline do ambiente)
| filter users_disabled >= 5

// Exclusão: ignora desativações realizadas pela conta de automação conhecida (reduz falso positivo)
| filter SubjectUserName != "<IDENTITY_PROVISIONING_ACCOUNT>"

// Ordenação: destaca os maiores volumes de desativação
| sort desc users_disabled
